root='F:\AER_RETRA_CASE'; base=fullfile(root,'CCN_FULL_RERUN_20260821','month_202206'); ds=dir(fullfile(base,'2022_06_*','orbit_*','CCN_grid_hdfqc.mat')); assert(~isempty(ds)); S=zeros(36,72,3); C=zeros(36,72); total=0; valid=0;
for k=1:numel(ds), A=load(fullfile(ds(k).folder,ds(k).name)); S=S+A.sumC; C=C+A.cnt; total=total+A.total; valid=valid+A.valid; end
M=nan(36,72,3); for q=1:3, z=S(:,:,q); ok=C>0; z(ok)=z(ok)./C(ok); M(:,:,q)=z; end
out=fullfile(base,'CCN_partial_3orbits.mat'); save(out,'M','C','total','valid','-v7.3'); lon=-177.5:5:177.5; lat=-87.5:5:87.5; [X,Y]=meshgrid(lon,lat); ss=[.15 .25 .40]; f=figure('Color','w','Position',[50 50 1500 760]); tiledlayout(2,2,'TileSpacing','compact','Padding','compact');
for q=1:3, nexttile; D=M(:,:,q); D(D<=0)=NaN; contourf(X,Y,max(2,min(7,log10(D))),35,'LineStyle','none'); set(gca,'YDir','normal'); xlim([-180 180]); ylim([-90 90]); hold on; load coastlines; plot(coastlon,coastlat,'Color',[.25 .25 .25],'LineWidth',.55); hold off; grid on; box on; title(sprintf('CCN %.2f%%',ss(q))); xlabel('Longitude'); ylabel('Latitude'); caxis([2 7]); end
nexttile; axis off; text(.05,.78,'Partial orbit test','FontSize',18,'FontWeight','bold'); text(.05,.60,sprintf('Valid orbit grids: %d',numel(ds)),'FontSize',13); text(.05,.45,'Logarithmic scale, HDF QC','FontSize',12); colormap(parula(35)); cb=colorbar; cb.Layout.Tile='east'; cb.Label.String='log_{10}(CCN cm^{-3})'; cb.Ticks=2:7; cb.TickLabels={'10^2','10^3','10^4','10^5','10^6','10^7'}; sgtitle('Partial Global CCN Distribution','FontSize',20,'FontWeight','bold'); exportgraphics(f,fullfile(base,'CCN_partial_3orbits.png'),'Resolution',180); close(f);
